    else имена = Array.from({length: ш}, (_, j) => 'Столбец ' + (j + 1));
    /* повторы имён — с номером */
    const было = {}; имена = имена.map(x => { if(было[x]){ было[x]++; return x + ' (' + было[x] + ')'; } было[x] = 1; return x; });
    return {заголовки: имена, строки: ряды.map(норм)};
  }
  /* JSON: массив записей — сам по себе, по пути «data.items» или первый найденный */
  function json(текст, путь){
    let d = typeof текст === 'string' ? JSON.parse(текст.replace(/^﻿/, '')) : текст;
    if(путь) for(const k of String(путь).split('.').filter(Boolean)){ if(d == null || !(k in d)) throw new Error('В JSON нет «' + путь + '»: остановился на «' + k + '»'); d = d[k]; }
    if(!Array.isArray(d)){
      const очередь = [d]; let найдено = null;
      while(очередь.length && !найдено){ const x = очередь.shift(); if(x && typeof x === 'object') for(const v of Object.values(x)){ if(Array.isArray(v) && v.length && v.some(e => e && typeof e === 'object')){ найдено = v; break; } if(v && typeof v === 'object') очередь.push(v); } }
      d = найдено || [d];
    }
    const плоско = (о, пре, out) => {
      if(о === null || typeof о !== 'object'){ out[пре || 'Значение'] = о; return out; }
      if(Array.isArray(о)){ out[пре || 'Значение'] = о.every(x => x === null || typeof x !== 'object') ? о.join(', ') : JSON.stringify(о).slice(0, 2000); return out; }
      for(const [k, v] of Object.entries(о)) плоско(v, пре ? пре + '.' + k : k, out);
      return out;
    };
    const записи = d.map(x => плоско(x, '', {}));
    const имена = []; for(const з of записи) for(const k of Object.keys(з)) if(!имена.includes(k)) имена.push(k);
    return {заголовки: имена, строки: записи.map(з => имена.map(k => з[k] === undefined ? null : (typeof з[k] === 'boolean' ? (з[k] ? 'да' : 'нет') : з[k])))};
  }
  /* XML: свой разбор (в потоке нет DOMParser) */
  const СУЩ = {lt: '<', gt: '>', amp: '&', quot: '"', apos: "'"};
  const сущности = s => s.replace(/&(#x[0-9a-f]+|#\d+|\w+);/gi, (m, k) => k[0] === '#' ? String.fromCodePoint(k[1] === 'x' || k[1] === 'X' ? parseInt(k.slice(2), 16) : +k.slice(1)) : (СУЩ[k] || m));
  function xmlДерево(т){
    т = String(т || '').replace(/^﻿/, '');
    const корень = {имя: '#корень', атр: {}, дети: [], текст: ''}, стек = [корень];
    let i = 0;
    while(i < т.length){
      const lt = т.indexOf('<', i);
      const верх = стек[стек.length - 1];
      if(lt < 0){ верх.текст += сущности(т.slice(i)); break; }
      if(lt > i) верх.текст += сущности(т.slice(i, lt));
      if(т.startsWith('<!--', lt)){ const e = т.indexOf('-->', lt); i = e < 0 ? т.length : e + 3; continue; }
      if(т.startsWith('<![CDATA[', lt)){ const e = т.indexOf(']]>', lt); верх.текст += т.slice(lt + 9, e < 0 ? т.length : e); i = e < 0 ? т.length : e + 3; continue; }
      if(т[lt + 1] === '?' || т[lt + 1] === '!'){ const e = т.indexOf('>', lt); i = e < 0 ? т.length : e + 1; continue; }
      let j = lt + 1, кав = null;
      while(j < т.length){ const ch = т[j]; if(кав){ if(ch === кав) кав = null; } else if(ch === '"' || ch === "'") кав = ch; else if(ch === '>') break; j++; }
      const тег = т.slice(lt + 1, j);
      i = j + 1;
      if(тег[0] === '/'){ const имя = тег.slice(1).trim(); for(let k = стек.length - 1; k > 0; k--) if(стек[k].имя === имя){ стек.length = k; break; } continue; }
