const копия = т => ({заголовки: т.заголовки.slice(), строки: т.строки.map(р => р.slice()), виды: т.виды ? т.виды.slice() : null});

/* ---------- источники ---------- */
function разобратьТекст(текст, вид, п, имя){
  const ф = вид === 'Авто' ? (/\.json$/i.test(имя || '') || /^\s*[\[{]/.test(текст) ? 'JSON' : /\.xml$/i.test(имя || '') || /^\s*</.test(текст) ? 'XML' : 'CSV') : вид;
