  try { т = await выполнить(таблица, шаги); } catch(e){ панель.сообщение(e.message); панель.поле('итог', [{текст: e.message, цвет: '#c92a2a'}]); return; }
  панель.список('столбец', т.заголовки); панель.список('столбцы', т.заголовки);
  панель.список('шаги', шаги.map(описаниеШага));
  const л = await книга.черновик(ПРЕДПРОСМОТР);
  const прежнее = лист(ПРЕДПРОСМОТР).память('показано') || null;
  const р = await вывести(л, ПРЕДПРОСМОТР, 0, 0, {заголовки: т.заголовки, строки: т.строки.slice(0, ПОКАЗ), виды: т.виды}, прежнее);
  лист(ПРЕДПРОСМОТР).запомнить('показано', р);
  книга.выделить(ПРЕДПРОСМОТР + '!A1');
  const части = [{текст: (источник ? источник.имя + ': ' : '') + т.строки.length.toLocaleString('ru-RU') + ' строк, ' + т.заголовки.length + ' столбцов', жирный: true}, {текст: т.строки.length > ПОКАЗ ? ' · в предпросмотре первые ' + ПОКАЗ : ''}];
  панель.поле('итог', части); панель.поле('загружено', части);
}

/* ---------- функции плагина ---------- */
async function безСбоя(f){ try { return await f(); } catch(e){ панель.сообщение(e.message); const ч = [{текст: e.message, цвет: '#c92a2a'}]; панель.поле('итог', ч); панель.поле('загружено', ч); панель.поле('выкладка', ч); } }
const ВИД_ИСТ = {'Файл': 'файл', 'Папка однотипных файлов': 'папка', 'По адресу': 'адрес', 'Выделенная таблица': 'таблица'};
async function Загрузить(){ return безСбоя(async () => {
  const п = параметры({});
  const ист = {вид: ВИД_ИСТ[п.источник] || 'файл'};
  const т = await загрузить(ист, п, false);
  if(!т) return;
  таблица = т; источник = ист; шаги = [];
  await показать();
  панель.сообщение('Загружено: ' + т.строки.length + ' строк. Добавляйте шаги на вкладке «Шаги» — предпросмотр на черновом листе обновится.');
}); }
function собратьШаг(п){
  const ш = {вид: п.видШага};
  const нужно = {столбец: ['Переименовать', 'Фильтр строк', 'Тип столбца', 'Разбить столбец', 'Группировать', 'Сортировать', 'Заменить', 'Очистить текст', 'Подтянуть из таблицы'],
    столбцы: ['Оставить столбцы', 'Удалить столбцы', 'Объединить столбцы', 'Отменить свёртку', 'Группировать', 'Удалить дубликаты']};
  if(нужно.столбец.includes(ш.вид)){ if(!п.столбец) throw new Error('Выберите столбец'); ш.столбец = п.столбец; }
  if(нужно.столбцы.includes(ш.вид)){ ш.столбцы = Array.isArray(п.столбцы) ? п.столбцы : String(п.столбцы || '').split(/\s*,\s*/).filter(Boolean); if(!ш.столбцы.length && !['Удалить дубликаты'].includes(ш.вид)) throw new Error('Отметьте столбцы в списке «Столбцы»'); }
  const свои = {'Фильтр строк': ['условие', 'значение'], 'Первые строки': ['значение'], 'Переименовать': ['имя'], 'Объединить столбцы': ['имя', 'разделитель'], 'Группировать': ['имя', 'функция'],
    'Новый столбец': ['имя', 'выражение'], 'Тип столбца': ['тип'], 'Разбить столбец': ['разделитель'], 'Сортировать': ['порядок'], 'Очистить текст': ['регистр'], 'Заменить': ['что', 'чем'],
    'Отменить свёртку': ['атрибут', 'назвЗнач'], 'Подтянуть из таблицы': ['таблица', 'ключ']}[ш.вид] || [];
  /* поле разделителя шага в панели — «разделительШага» (у источника свой «разделитель»), в шаге — «разделитель» */
  for(const k of свои){ const v = k === 'разделитель' ? п.разделительШага : п[k]; if(v !== undefined && v !== null) ш[k] = v; }
  if(ш.вид === 'Подтянуть из таблицы') ш.взять = String(п.взять || '').split(/\s*,\s*/).filter(Boolean);
  return ш;
}
async function ДобавитьШаг(){ return безСбоя(async () => {
  if(!таблица) throw new Error('Сначала загрузите данные на вкладке «Источник»');
  const ш = собратьШаг(параметры({}));
  const пробные = шаги.concat([ш]);
  await выполнить(таблица, пробные);           /* ошибка — словами, шаг не добавляется */
  шаги = пробные; await показать();
  for(const k of ['имя', 'выражение', 'значение', 'что', 'чем']) панель.поле(k, '');
}); }
async function УдалитьШаг(){ return безСбоя(async () => {
  const выб = параметры({}).шаги; const i = шаги.map(описаниеШага).indexOf(выб);
  if(i < 0) throw new Error('Выберите шаг в списке');
  шаги.splice(i, 1); await показать();
}); }
async function ШагВыше(){ return безСбоя(async () => { const i = шаги.map(описаниеШага).indexOf(параметры({}).шаги); if(i > 0){ [шаги[i - 1], шаги[i]] = [шаги[i], шаги[i - 1]]; await показать(); } }); }
async function Выложить(){ return безСбоя(async () => {
  if(!таблица) throw new Error('Сначала загрузите данные');
  const п = параметры({});
  const т = await выполнить(таблица, шаги);
  let имяЛиста, r0 = 0, c0 = 0, л;
  if(п.куда === 'На этот лист от выделенной клетки'){
    const в = книга.выделение;
    if(!в || в.лист === ПРЕДПРОСМОТР) throw new Error('Перейдите на свой лист и выделите клетку, откуда класть данные');
    имяЛиста = в.лист; r0 = в.r1 - 1; c0 = в.c1 - 1; л = лист(имяЛиста);
  } else {
    имяЛиста = String(п.имяЛиста || 'Данные').trim().slice(0, 31).replace(/[\\/?*[\]:]/g, ' ');
    л = await книга.черновик(имяЛиста);
  }
  const запросы = (лист(имяЛиста).память('загрузки') || []).filter(з => !(з.r0 === r0 && з.c0 === c0));
  const прежний = (лист(имяЛиста).память('загрузки') || []).find(з => з.r0 === r0 && з.c0 === c0);
  const р = await вывести(л, имяЛиста, r0, c0, т, прежний ? прежний.размер : null);
  запросы.push({источник: Object.assign({}, источник), настройки: {формат: п.формат, разделитель: п.разделитель, кодировка: п.кодировка, путьJSON: п.путьJSON, элементXML: п.элементXML, заголовки: п.заголовки, типы: п.типы, листКниги: п.листКниги, адрес: п.адрес}, шаги, r0, c0, размер: р, когда: new Date().toLocaleString('ru-RU')});
  лист(имяЛиста).запомнить('загрузки', запросы);
  книга.выделить(имяЛиста + '!' + АДРЕС(r0, c0));
  панель.сообщение('Выложено ' + т.строки.length.toLocaleString('ru-RU') + ' строк на лист «' + имяЛиста + '» от ' + АДРЕС(r0, c0) + '. Шаги сохранены в книге: «Обновить» повторит их.' + (п.куда === 'На этот лист от выделенной клетки' ? '' : ' Лист черновой — ✓ на ярлычке, чтобы оставить его в книге.'));
}); }
/* обновить: загрузки текущего листа заново — источник, шаги, то же место */
async function Обновить(){ return безСбоя(async () => {
  const в = книга.выделение; const имяЛиста = в && в.лист;
  const запросы = (имяЛиста && лист(имяЛиста).память('загрузки')) || [];
  if(!запросы.length) throw new Error('На листе «' + имяЛиста + '» нет загрузок плагина');
  let n = 0;
  for(const з of запросы){
    const т0 = await загрузить(Object.assign({}, з.источник), з.настройки, true);
    if(!т0) continue;
    const т = await выполнить(т0, з.шаги);
    з.размер = await вывести(лист(имяЛиста), имяЛиста, з.r0, з.c0, т, з.размер);
    з.когда = new Date().toLocaleString('ru-RU'); n++;
  }
  лист(имяЛиста).запомнить('загрузки', запросы);
  панель.сообщение('Обновлено загрузок: ' + n + ' из ' + запросы.length);
  панель.поле('выкладка', [{текст: 'Обновлено загрузок: ' + n + ' из ' + запросы.length + ' (' + new Date().toLocaleTimeString('ru-RU') + ')', цвет: '#2b8a3e'}]);
}); }
/* быстрые команды над выделенным */
async function быстро(шаг){
  const в = книга.выделение;
  if(!в || (в.r2 - в.r1 < 1 && в.c2 - в.c1 < 1)) throw new Error('Выделите таблицу с шапкой');
  const ист = {вид: 'таблица'};
  const т0 = await загрузить(ист, {заголовки: true, типы: false}, false);
  const т = await применить(т0, шаг(т0));
  const л = await книга.черновик('Результат');
  await вывести(л, 'Результат', 0, 0, т, лист('Результат').память('показано'));
  лист('Результат').запомнить('показано', {строк: т.строки.length + 1, столбцов: т.заголовки.length});
  книга.выделить('Результат!A1');
  панель.сообщение('Готово: ' + т.строки.length + ' строк на черновом листе «Результат» (✓ на ярлычке — оставить).');
}
async function БыстроРазвернуть(){ return безСбоя(() => быстро(т => ({вид: 'Отменить свёртку', столбцы: [т.заголовки[0]]}))); }
async function БыстроТранспонировать(){ return безСбоя(() => быстро(() => ({вид: 'Транспонировать'}))); }
